@meta {
  id: "acme-support"
  syntax: "1.6.0"
  owner: "team-support"
  risk: "medium"
}

@context {
  """
  Acme Cloud runs in two regions.
  """
  - "Be brief"
  - "Be kind"
  product: "Acme Cloud"
  tier: "enterprise"
}

@prompts {
  mixed: {
    description: "Answer with a block of text, list items and properties"
    compose: [context]
    system: "Answer the question."
    user: "Question: {{input.question}}"
    inputs: { question: { type: "string", description: "The question" } }
  }
}
